import{_ as t,o as a,c as o,ae as r}from"./chunks/framework.EHGTsUvI.js";const p=JSON.parse('{"title":"Cows","description":"","frontmatter":{"title":"Cows"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Animals/cows.md","filePath":"Main/Main/GeneralKnowledge/Animals/cows.md"}'),i={name:"Main/Main/GeneralKnowledge/Animals/cows.md"};function n(l,e,s,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="cows" tabindex="-1">Cows <a class="header-anchor" href="#cows" aria-label="Permalink to &quot;Cows&quot;">​</a></h1><p>Cows are a livestock animal used to produce <strong>Milk</strong>. Milk is an important ingredient for several production chains, including the <strong>Cheese Factory</strong>, <strong>Cake Factory</strong>, and <strong>Chocolate Milk Factory</strong>.</p><h2 id="how-to-obtain" tabindex="-1">How to Obtain <a class="header-anchor" href="#how-to-obtain" aria-label="Permalink to &quot;How to Obtain&quot;">​</a></h2><p>Cows can be purchased from <strong>AnimalCo</strong>.</p><p>To purchase cows:</p><ol><li>Take a suitable trailer to AnimalCo.</li><li>Position the trailer in the marked animal purchase area.</li><li>Enter AnimalCo and select the cows you want to purchase.</li><li>The cows will be loaded into the trailer.</li><li>Transport them back to your farm.</li><li>Place them into a suitable fenced area with access to a barn and feeder.</li></ol><p>A trailer capable of carrying <strong>large animals</strong> is required.</p><p>Suitable trailers include:</p><ul><li>Insul</li><li>LAT 360</li><li>Medium Animal Trailer</li><li>Animal Hauler S-1500</li></ul><h2 id="purchase-price" tabindex="-1">Purchase Price <a class="header-anchor" href="#purchase-price" aria-label="Permalink to &quot;Purchase Price&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Purchase Price</td><td>4,500 Coins per Cow</td></tr><tr><td>Animal Type</td><td>Large Animal</td></tr></tbody></table><p>A cow costs <strong>4,500 Coins</strong> when purchased from AnimalCo.</p><h2 id="housing-requirements" tabindex="-1">Housing Requirements <a class="header-anchor" href="#housing-requirements" aria-label="Permalink to &quot;Housing Requirements&quot;">​</a></h2><p>Cows require a suitable fenced area and access to a barn for milking.</p><p>Cows can be kept in both <strong>manual</strong> and <strong>automatic</strong> milking barns.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Details</th></tr></thead><tbody><tr><td>Fenced Area</td><td>Required</td></tr><tr><td>Barn</td><td>Required for milking</td></tr><tr><td>Feeder</td><td>Regular Feeder</td></tr><tr><td>Animal Food</td><td>Required</td></tr><tr><td>Animal Type</td><td>Large Animal</td></tr></tbody></table><p>Manual barns require the player to collect the milk from the individual stalls.</p><p>Automatic barns collect the milk at a designated collection area outside the barn, where it can be collected using a suitable tanker.</p><h2 id="food-requirements" tabindex="-1">Food Requirements <a class="header-anchor" href="#food-requirements" aria-label="Permalink to &quot;Food Requirements&quot;">​</a></h2><p>Cows eat <strong>Animal Food</strong>.</p><p>Animal Food can be purchased from <strong>AnimalCo</strong> or produced using an <strong>Animal Food Factory</strong>.</p><p>Cows use a <strong>Regular Feeder</strong>, which should be placed within their fenced area.</p><blockquote><p><strong>Important:</strong> Keep the feeder stocked with Animal Food to maintain your cows and their milk production.</p></blockquote><h2 id="products-produced" tabindex="-1">Products Produced <a class="header-anchor" href="#products-produced" aria-label="Permalink to &quot;Products Produced&quot;">​</a></h2><p>Cows can produce three types of milk:</p><table tabindex="0"><thead><tr><th>Product</th><th>Details</th></tr></thead><tbody><tr><td>Regular Milk</td><td>Can be used in milk-based factories</td></tr><tr><td>Free-Range Milk</td><td>Higher-value milk that can provide increased factory efficiency</td></tr><tr><td>Spoiled Milk</td><td>Cannot be used in factories</td></tr></tbody></table><p>Regular and Free-Range Milk can be used in milk-based production chains.</p><p>Free-Range Milk can provide increased efficiency when used in factories. In the Chocolate Milk Factory, <strong>1 Free-Range Milk counts as 2 Regular Milk</strong> according to current production documentation.</p><p>Spoiled Milk cannot be used in factories.</p><h3 id="milk-production-uses" tabindex="-1">Milk Production Uses <a class="header-anchor" href="#milk-production-uses" aria-label="Permalink to &quot;Milk Production Uses&quot;">​</a></h3><p>Cow milk is used in several production chains, including:</p><ul><li><strong>Cheese Factory</strong></li><li><strong>Cake Factory</strong></li><li><strong>Chocolate Milk Factory</strong></li></ul><p>Chocolate Milk is particularly valuable and is considered one of the strongest late-game production methods.</p><h2 id="production-time" tabindex="-1">Production Time <a class="header-anchor" href="#production-time" aria-label="Permalink to &quot;Production Time&quot;">​</a></h2><p>A fixed milk production time is <strong>not currently reliably documented</strong>.</p><p>Milk production depends on the cow and barn setup, with the game supporting both manual and automatic milking systems.</p><blockquote><p><strong>Note:</strong> A specific production time should be added once confirmed in-game rather than using an unverified value.</p></blockquote><h2 id="selling-information" tabindex="-1">Selling Information <a class="header-anchor" href="#selling-information" aria-label="Permalink to &quot;Selling Information&quot;">​</a></h2><p>Milk can be sold at <strong>AnimalCo</strong> or at the appropriate animal-product selling point.</p><p>Milk can also be processed into higher-value products before being sold.</p><table tabindex="0"><thead><tr><th>Product</th><th>Selling Information</th></tr></thead><tbody><tr><td>Regular Milk</td><td>Can be sold or used in factories</td></tr><tr><td>Free-Range Milk</td><td>Can be sold or used in factories</td></tr><tr><td>Spoiled Milk</td><td>Cannot be used in factories</td></tr></tbody></table><p>For maximum value, milk can be used as an ingredient in production chains such as <strong>Chocolate Milk</strong> rather than being sold immediately.</p><p>Chocolate Milk is particularly valuable, with current community documentation listing approximately <strong>20,000 Coins per jug</strong>.</p><h2 id="required-license" tabindex="-1">Required License <a class="header-anchor" href="#required-license" aria-label="Permalink to &quot;Required License&quot;">​</a></h2><table tabindex="0"><thead><tr><th>License</th><th>Required</th></tr></thead><tbody><tr><td>Cow / Animal License</td><td>Yes</td></tr></tbody></table><p>Cows are unlocked through the <strong>Animals Goals</strong> progression.</p><p>The Animals Goals track is also used to unlock the systems required for advanced livestock and factory production.</p><h2 id="other-useful-information" tabindex="-1">Other Useful Information <a class="header-anchor" href="#other-useful-information" aria-label="Permalink to &quot;Other Useful Information&quot;">​</a></h2><ul><li>Cows cost <strong>4,500 Coins</strong> each.</li><li>Cows are classified as <strong>large animals</strong>.</li><li>Cows require a <strong>Regular Feeder</strong>.</li><li>Cows require <strong>Animal Food</strong>.</li><li>Cows need a suitable fenced area.</li><li>Cows can be milked using either <strong>manual or automatic barns</strong>.</li><li>There are currently <strong>7 different barns</strong>, with 2 automatic and 5 manual.</li><li>Cows produce <strong>Regular, Free-Range, and Spoiled Milk</strong>.</li><li>Spoiled Milk cannot be used in factories.</li><li>Free-Range Milk provides better ingredient efficiency in milk-based factories.</li><li>Milk is used in the <strong>Cheese Factory</strong>, <strong>Cake Factory</strong>, and <strong>Chocolate Milk Factory</strong>.</li><li>Cows are particularly useful for the <strong>Chocolate Milk production chain</strong>.</li><li>A suitable large-animal trailer is required when purchasing cows.</li><li>Milk and other animal products can be sold at <strong>AnimalCo</strong>.</li></ul>',49)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
